SELECT * FROM xsy_sales_order WHERE deleted = FALSE AND order_source = 'MALL' AND seller_id IS NULL AND status IN ('DRAFT', 'PENDING', 'CONFIRMED') AND status = #{query.status}
AND (order_no ILIKE CONCAT('%', #{query.keyword}, '%') OR customer_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY created_at DESC, id DESC

mapper.update:
UPDATE xsy_sales_order
SET seller_id = #{sellerId}, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{orderId}
    AND version = #{version}
    AND seller_id IS NULL
    AND order_source = 'MALL'
    AND status IN ('DRAFT', 'PENDING', 'CONFIRMED')
    AND deleted = FALSE

UPDATE xsy_sales_order
SET deleted = TRUE, version = version + 1, updated_at = CURRENT_TIMESTAMP, updated_by = #{operator}
WHERE id = #{id}
    AND version = #{version}
    AND deleted = FALSE

